import re,os
decls=[]
for root,dirs,files in os.walk('internal'):
    for fn in files:
        if not fn.endswith('.go') or fn.endswith('_test.go'): continue
        p=os.path.join(root,fn)
        for i,line in enumerate(open(p,errors='ignore').read().split('\n'),1):
            m=re.match(r'func (\([^)]*\)\s*)?([A-Za-z_][A-Za-z0-9_]*)\(',line)
            if m: decls.append((m.group(2),p,i,bool(m.group(1))))
allf=[]
for root,dirs,files in os.walk('.'):
    dirs[:]=[d for d in dirs if d not in ('node_modules','.git','web')]
    for fn in files:
        if fn.endswith('.go'): allf.append(os.path.join(root,fn))
texts={p:open(p,errors='ignore').read() for p in allf}
res=[]
for name,p,i,ismeth in decls:
    pat=re.compile(r'(?<![A-Za-z0-9_])'+re.escape(name)+r'\s*\(')
    n=0;nprod=0;fs=set()
    for f,t in texts.items():
        for line in t.split('\n'):
            if re.match(r'func ',line): continue
            if pat.search(line):
                n+=1; fs.add(f)
                if not f.endswith('_test.go'): nprod+=1
    res.append((nprod,n,name,f"{p}:{i}",ismeth,len(fs)))
res.sort(reverse=True)
seen=set()
for r in res[:25]:
    if r[2] in seen: continue
    seen.add(r[2]); print(r)
EOF

